/* Example Task Mapping */
/* Database Schema: */
CREATE TABLE student (
    student_id int,
    name text,
    age int,
    major_id int
);
CREATE TABLE major (
    major_id int,
    major_name text
);
/* Question: Find the total number of students in each major, sorted from highest to lowest enrollment count. */
SQL: SELECT T2.major_name, COUNT(T1.student_id) FROM student AS T1 JOIN major AS T2 ON T1.major_id = T2.major_id GROUP BY T2.major_name ORDER BY COUNT(T1.student_id) DESC;

